+				details: 'Uncovered: ac-2'
+			}
+		],
+		traitCycles: []
+	};
+}
+
+/** Mock validation response with no issues. */
+function mockValidationClean() {
+	return {
+		valid: true,
+		schemaErrors: [],
+		refErrors: [],
+		refWarnings: [],
+		orphans: [],
+		completenessWarnings: [],
+		traitCycles: []
